<template>
  <el-card>
    <div slot="header"><i class="el-icon-refund"></i> 退费审批管理</div>
    <div class="toolbar">
      <div class="toolbar-left">
        <el-radio-group v-model="statusTab" @change="switchTab" size="small">
          <el-radio-button :label="0">待审核</el-radio-button>
          <el-radio-button :label="1">已通过</el-radio-button>
          <el-radio-button :label="2">已拒绝</el-radio-button>
        </el-radio-group>
        <el-input v-model="query" placeholder="搜索退费单号/患者ID" clearable size="small" class="search-input" @keyup.enter.native="loadData">
          <el-button slot="append" icon="el-icon-search" @click="loadData"></el-button>
        </el-input>
      </div>
      <div class="toolbar-right">
        <el-tag class="total-tag">共 {{ total }} 条</el-tag>
      </div>
    </div>
    <el-table :data="refundData" stripe border>
      <el-table-column label="编号" prop="rfId" width="70" align="center"></el-table-column>
      <el-table-column label="订单ID" prop="oId" width="75" align="center"></el-table-column>
      <el-table-column label="批次ID" prop="brId" width="75" align="center"></el-table-column>
      <el-table-column label="退费金额" width="90" align="center">
        <template slot-scope="s">¥{{ s.row.rfAmount || '0' }}</template>
      </el-table-column>
      <el-table-column label="退费原因" prop="rfReason" min-width="180" show-overflow-tooltip></el-table-column>
      <el-table-column label="申请人" prop="rfRequester" width="90" align="center"></el-table-column>
      <el-table-column label="申请时间" prop="rfCreateTime" width="160"></el-table-column>
      <el-table-column label="状态" width="80" align="center">
        <template slot-scope="s">
          <el-tag v-if="s.row.rfStatus===0" type="warning" size="mini">待审核</el-tag>
          <el-tag v-else-if="s.row.rfStatus===1" type="success" size="mini">已通过</el-tag>
          <el-tag v-else type="danger" size="mini">已拒绝</el-tag>
        </template>
      </el-table-column>
      <el-table-column label="操作" width="160" fixed="right" align="center">
        <template slot-scope="s">
          <template v-if="s.row.rfStatus===0">
            <el-button type="success" size="mini" @click="approveDialog(s.row)">通过</el-button>
            <el-button type="danger" size="mini" @click="rejectDialog(s.row)">拒绝</el-button>
          </template>
          <el-tag v-else type="info" size="mini">已处理</el-tag>
        </template>
      </el-table-column>
    </el-table>
    <el-pagination @size-change="s=>{size=s;loadData()}" @current-change="p=>{pageNumber=p;loadData()}" background
      layout="total,sizes,prev,pager,next,jumper" :current-page="pageNumber" :page-size="size"
      :page-sizes="[10,20,50]" :total="total"></el-pagination>

    <el-dialog title="审批确认" :visible.sync="approveDlgVisible" width="420px">
      <span>确定通过该退费申请吗？</span>
      <div v-if="selectedRefund" style="margin-top:10px;font-size:13px;color:#606266;">
        <p>退费编号：{{ selectedRefund.rfId }} | 金额：¥{{ selectedRefund.rfAmount }}</p>
        <p>原因：{{ selectedRefund.rfReason }}</p>
      </div>
      <div slot="footer">
        <el-button @click="approveDlgVisible=false">取消</el-button>
        <el-button type="success" @click="doApprove">确定通过</el-button>
      </div>
    </el-dialog>

    <el-dialog title="拒绝退费" :visible.sync="rejectDlgVisible" width="420px">
      <el-form :model="rejectForm" label-width="80px" size="small">
        <el-form-item label="拒绝原因"><el-input v-model="rejectForm.reason" type="textarea" :rows="3" placeholder="请输入拒绝原因"></el-input></el-form-item>
      </el-form>
      <div slot="footer">
        <el-button @click="rejectDlgVisible=false">取消</el-button>
        <el-button type="danger" @click="doReject">确定拒绝</el-button>
      </div>
    </el-dialog>
  </el-card>
</template>
<script>
import request from "@/utils/request.js";
export default {
  name: "RefundApproval",
  data() {
    return {
      pageNumber:1, size:10, query:"", statusTab:0, refundData:[], total:0,
      approveDlgVisible:false, selectedRefund:null,
      rejectDlgVisible:false, rejectForm:{ reason:"" }
    };
  },
  methods: {
    loadData() {
      request.get("refundRequest/findAll",{params:{pageNumber:this.pageNumber,size:this.size,query:this.query,status:this.statusTab}})
        .then(r=>{const d=r.data.data;this.refundData=d.records||[];this.total=d.total||0;});
    },
    switchTab() {
      this.pageNumber=1; this.loadData();
    },
    approveDialog(row) {
      this.selectedRefund=row; this.approveDlgVisible=true;
    },
    rejectDialog(row) {
      this.selectedRefund=row; this.rejectForm={ reason:"" }; this.rejectDlgVisible=true;
    },
    doApprove() {
      if(!this.selectedRefund) return;
      request.post("refundRequest/approve",{rfId:this.selectedRefund.rfId}).then(r=>{
        if(r.data.status===200){ this.$message.success("已通过退费申请"); this.approveDlgVisible=false; this.loadData(); }
        else this.$message.error(r.data.msg||"操作失败");
      });
    },
    doReject() {
      if(!this.selectedRefund) return;
      request.post("refundRequest/reject",{rfId:this.selectedRefund.rfId, reason:this.rejectForm.reason}).then(r=>{
        if(r.data.status===200){ this.$message.success("已拒绝退费申请"); this.rejectDlgVisible=false; this.loadData(); }
        else this.$message.error(r.data.msg||"操作失败");
      });
    },
    handleSizeChange(s){this.size=s;this.loadData();},
    handleCurrentChange(p){this.pageNumber=p;this.loadData();}
  },
  created(){this.loadData();}
};
</script>
