<template>
  <el-card>
    <div slot="header">
      <i class="el-icon-s-data"></i> 医生个人统计
      <el-button size="mini" type="primary" plain style="float:right;margin-left:8px;" @click="exportReport">
        <i class="el-icon-download"></i> 导出工作报表
      </el-button>
    </div>

    <div class="search-row">
      <el-date-picker v-model="month" type="month" placeholder="选择统计月份" value-format="yyyy-MM" size="small" @change="loadStats"></el-date-picker>
    </div>

    <el-row :gutter="16" style="margin-bottom:16px;">
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#409EFF;"><i class="el-icon-user"></i></div>
            <div class="stat-info"><div class="stat-num">{{ stats.visitCount }}</div><div class="stat-label">接诊人次</div></div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#67C23A;"><i class="el-icon-document-copy"></i></div>
            <div class="stat-info"><div class="stat-num">{{ stats.prescriptionCount }}</div><div class="stat-label">处方数量</div></div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#E6A23C;"><i class="el-icon-monitor"></i></div>
            <div class="stat-info"><div class="stat-num">{{ stats.checkCount }}</div><div class="stat-label">检查开具数量</div></div>
          </div>
        </el-card>
      </el-col>
      <el-col :span="6">
        <el-card shadow="hover" class="stat-card">
          <div class="stat-inner">
            <div class="stat-icon" style="background:#F56C6C;"><i class="el-icon-s-finance"></i></div>
            <div class="stat-info"><div class="stat-num">¥{{ stats.avgCost }}</div><div class="stat-label">平均费用</div></div>
          </div>
        </el-card>
      </el-col>
    </el-row>

    <el-card>
      <div slot="header">月度接诊趋势</div>
      <div id="chartMonthly" style="width:100%;height:300px;"></div>
    </el-card>
  </el-card>
</template>
<script>
import request from "@/utils/request.js";
import {getToken} from "@/utils/storage.js";
import jwtDecode from "jwt-decode";
export default {
  name: "DoctorStatsPanel",
  data() {
    return {
      month: "",
      stats:{ visitCount:0, prescriptionCount:0, checkCount:0, avgCost:"0.00" },
      chartData:[]
    };
  },
  methods: {
    getDoctorId() {
      try{ const t=getToken(); if(t){ const d=jwtDecode(t); return d.dId||""; } }catch(e){}
      return "";
    },
    loadStats() {
      if(!this.month){ this.loadDefaultMonth(); return; }
      this.stats={ visitCount:0, prescriptionCount:0, checkCount:0, avgCost:"0.00" };
      this.chartData=[];
      const dId=this.getDoctorId();
      if(!dId) return this.$message.warning("无法获取医生信息");
      // Load completed orders for the month
      request.get("order/findOrderFinish",{params:{pageNumber:1,size:999,query:this.month,dId}}).then(r=>{
        const records=r.data.data.records||[];
        this.stats.visitCount=records.length;
        const totalFee=records.reduce((s,o)=>s+Number(o.oTotalPrice||0),0);
        this.stats.avgCost=this.stats.visitCount>0?(totalFee/this.stats.visitCount).toFixed(2):"0.00";
        this.stats.prescriptionCount=records.filter(o=>(o.oDrug&&o.oDrug!=="无")||(Number(o.oDrugFee||0)>0)).length;
        this.stats.checkCount=records.filter(o=>(o.oCheck&&o.oCheck!=="无")||(Number(o.oCheckFee||0)>0)).length;
        // Build monthly chart data
        this.buildChart(records);
      }).catch(()=>{
        this.$message.error("获取统计数据失败");
      });
    },
    buildChart(records) {
      if(!this.month) return;
      const yearMonth=this.month.split("-");
      const year=parseInt(yearMonth[0]), month=parseInt(yearMonth[1]);
      const daysInMonth=new Date(year,month,0).getDate();
      const daily=[];
      for(let d=1;d<=daysInMonth;d++){ daily.push({day:d,count:0}); }
      records.forEach(o=>{
        if(!o.oStart) return;
        const day=parseInt(o.oStart.substring(8,10));
        if(day>=1&&day<=daysInMonth) daily[day-1].count++;
      });
      this.chartData=daily;
      this.$nextTick(()=>this.renderChart());
    },
    renderChart() {
      const c=this.$echarts.init(document.getElementById("chartMonthly"));
      c.setOption({
        tooltip:{trigger:"axis"},
        grid:{left:40,right:20,bottom:30,top:20},
        xAxis:{type:"category",data:this.chartData.map(d=>d.day+"日"),axisLabel:{fontSize:11}},
        yAxis:{type:"value",minInterval:1},
        series:[{
          type:"bar",data:this.chartData.map(d=>d.count),
          itemStyle:{color:"#409EFF",borderRadius:[4,4,0,0]},
          barMaxWidth:30
        }]
      });
    },
    loadDefaultMonth() {
      const d=new Date();
      this.month=d.getFullYear()+"-"+(d.getMonth()+1).toString().padStart(2,"0");
      this.loadStats();
    },
    exportReport() {
      if(!this.stats.visitCount&&!this.stats.prescriptionCount) return this.$message.warning("暂无统计数据可导出");
      const lines=[];
      lines.push("医生个人工作报表");
      lines.push("统计月份："+this.month);
      lines.push("");
      lines.push("接诊人次,"+this.stats.visitCount);
      lines.push("处方数量,"+this.stats.prescriptionCount);
      lines.push("检查开具数量,"+this.stats.checkCount);
      lines.push("平均费用(元),"+this.stats.avgCost);
      lines.push("");
      lines.push("日期,接诊量");
      this.chartData.forEach(d=>{ lines.push(d.day+"日,"+d.count); });
      const csv=lines.join("\n");
      const b=new Blob(["﻿"+csv],{type:"text/csv;charset=utf-8"});
      const a=document.createElement("a"); a.href=URL.createObjectURL(b); a.download="医生工作报表_"+this.month+".csv"; a.click();
    }
  },
  created(){ this.loadDefaultMonth(); }
};
</script>
