<script>
import request from "@/utils/request.js";
export default {
  name: "dataExpore",
  data() {
    return {
      activeTab: "hospital",
      // 医院运营
      todayVisits: 0, todayDrugIncome: 0, todayRegIncome: 0, totalPatients: 0,
      sevenDate: [],
      // 医生统计
      selectedDoctor: "",
      doctorList: [],
      doctorPeriod: "7",
      doctorStats: null,
      // 药房统计
      pharmStats: { lowStockList: [], expiringBatches: [], expiredCount: 0, expiringCount: 0, drugTypeCount: 0, totalStock: 0 },
      drugConsumptionRank: [],
      // 收入分析
      incomePeriod: "20",
      incomeDetailList: [],
      incomeSummary: { total: "0.00", registration: "0.00", drugCheck: "0.00", dailyAvg: "0.00", maxDay: "0.00" }
    };
  },
  methods: {
    pastSeven(num) {
      var date = new Date();
      date.setDate(date.getDate() - num);
      return (date.getMonth() + 1) + "-" + date.getDate();
    },
    // =========== 医院运营 ===========
    loadHospitalStats() {
      request.get("order/orderPeople").then(r => {
        if (r.data.status === 200) this.todayVisits = r.data.data || 0;
      });
      request.get("order/orderDailyIncome").then(r => {
        if (r.data.status === 200) {
          var d = r.data.data;
          if (d && d.drugIncome && d.drugIncome.length) {
            this.todayDrugIncome = d.drugIncome[d.drugIncome.length - 1] || 0;
            this.todayRegIncome = d.regIncome ? d.regIncome[d.regIncome.length - 1] || 0 : 0;
          }
        }
      });
      request.get("patient/patientAge").then(r => {
        if (r.data.status === 200) {
          var ages = r.data.data || [];
          this.totalPatients = ages.reduce(function(s, v) { return s + (parseInt(v) || 0); }, 0);
        }
      });
      this.initDeptChart();
      this.initIncomeBarChart();
      this.initVisitTrend();
      this.initGenderChart();
      this.initAgeChart();
    },
    initDeptChart() {
      this.$nextTick(function() {
        var chart = document.getElementById("deptPieChart");
        if (!chart) return;
        var myChart = this.$echarts.init(chart);
        request.get("order/orderSection").then(res => {
          var raw = res.data.data || [];
          var data = raw.map(function(item) {
            return { value: item.countSection, name: item.doctor ? item.doctor.dSection : item.dSection || "未知" };
          });
          myChart.setOption({
            tooltip: { trigger: "item", formatter: "{b}: {c}人 ({d}%)" },
            legend: { bottom: 0, type: "scroll" },
            series: [{
              type: "pie", radius: ["35%", "60%"], center: ["50%", "45%"],
              data: data.length ? data : [{ value: 1, name: "暂无数据" }],
              label: { show: true, formatter: "{b}\n{d}%" }
            }]
          });
        });
      });
    },
    initIncomeBarChart() {
      this.$nextTick(function() {
        var chart = document.getElementById("incomeBarChart");
        if (!chart) return;
        var myChart = this.$echarts.init(chart);
        request.get("order/orderDailyIncome").then(res => {
          var d = res.data.data || {};
          var dates = d.dates || [];
          myChart.setOption({
            tooltip: { trigger: "axis" },
            legend: { data: ["药费+检查费", "挂号费"], bottom: 0 },
            xAxis: { type: "category", data: dates.slice(-7), axisLabel: { rotate: 20, fontSize: 10 } },
            yAxis: { type: "value" },
            grid: { left: 50, right: 20, bottom: 50, top: 20 },
            series: [
              { name: "药费+检查费", type: "bar", data: (d.drugIncome || []).slice(-7), itemStyle: { color: "#E6A23C" }, barWidth: "35%" },
              { name: "挂号费", type: "bar", data: (d.regIncome || []).slice(-7), itemStyle: { color: "#67C23A" }, barWidth: "35%" }
            ]
          });
        });
      });
    },
    initVisitTrend() {
      this.$nextTick(function() {
        var chart = document.getElementById("visitTrendChart");
        if (!chart) return;
        var myChart = this.$echarts.init(chart);
        request.get("order/orderSeven").then(res => {
          myChart.setOption({
            tooltip: { trigger: "axis" },
            grid: { left: 45, right: 20, bottom: 25, top: 10 },
            xAxis: { type: "category", data: this.sevenDate },
            yAxis: { type: "value", minInterval: 1 },
            series: [{
              data: res.data.data || [],
              type: "line", smooth: true,
              areaStyle: { color: "rgba(64,158,255,0.2)" },
              lineStyle: { color: "#409EFF" },
              itemStyle: { color: "#409EFF" }
            }]
          });
        });
      });
    },
    initGenderChart() {
      this.$nextTick(function() {
        var chart = document.getElementById("genderChart");
        if (!chart) return;
        var myChart = this.$echarts.init(chart);
        request.get("order/orderGender").then(res => {
          var d = res.data.data || [];
          var data = d.length ? d.map(function(item) {
            return { value: item.countGender, name: item.patient ? item.patient.pGender : "未知" };
          }) : [{ value: 1, name: "暂无数据" }];
          myChart.setOption({
            tooltip: { trigger: "item" },
            legend: { bottom: 0 },
            series: [{ type: "pie", radius: "55%", data: data }]
          });
        });
      });
    },
    initAgeChart() {
      this.$nextTick(function() {
        var chart = document.getElementById("ageChart");
        if (!chart) return;
        var myChart = this.$echarts.init(chart);
        request.get("patient/patientAge").then(res => {
          var labels = ["0-9","10-19","20-29","30-39","40-49","50-59","60-69","70-79","80-89","90-99"];
          var vals = (res.data.data || []).map(function(v) { return v || 0; });
          myChart.setOption({
            tooltip: { trigger: "item" },
            legend: { bottom: 0 },
            series: [{
              type: "pie", radius: ["40%", "70%"],
              data: labels.map(function(l, i) { return { value: vals[i], name: l }; }),
              label: { show: false },
              emphasis: { label: { show: true, fontSize: "16", fontWeight: "bold" } }
            }]
          });
        });
      });
    },
    exportSectionData() {
      request.get("order/orderSection").then(res => {
        var raw = res.data.data || [];
        var csv = "科室,挂号人数\n";
        raw.forEach(function(item) {
          csv += (item.doctor ? item.doctor.dSection : "未知") + "," + item.countSection + "\n";
        });
        this.downloadCsv(csv, "科室挂号占比.csv");
      });
    },
    exportIncomeData() {
      request.get("order/orderDailyIncome").then(res => {
        var d = res.data.data || {};
        var dates = d.dates || [];
        var csv = "日期,药费+检查费,挂号费\n";
        for (var i = 0; i < dates.length; i++) {
          csv += dates[i] + "," + ((d.drugIncome || [])[i] || 0) + "," + ((d.regIncome || [])[i] || 0) + "\n";
        }
        this.downloadCsv(csv, "收入构成.csv");
      });
    },

    // =========== 医生统计 ===========
    loadDoctorList() {
      request.get("doctor/findAllDoctors", { params: { pageNumber: 1, size: 200, query: "" } }).then(res => {
        if (res.data.status === 200) {
          var data = res.data.data;
          this.doctorList = data.doctors || data.records || [];
        }
      });
    },
    loadDoctorStats() {
      if (!this.selectedDoctor) return;
      this.doctorStats = null;
      var days = parseInt(this.doctorPeriod) || 7;
      var endDate = new Date();
      var startDate = new Date();
      startDate.setDate(startDate.getDate() - days);
      var fmt = function(d) { return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); };
      var start = fmt(startDate) + " 00:00";
      var end = fmt(endDate) + " 23:59";
      request.get("order/findOrdersByDate", { params: { start: start, end: end } }).then(res => {
        if (res.data.status === 200) {
          var allOrders = res.data.data || [];
          var docOrders = allOrders.filter(function(o) { return String(o.dId) === String(this.selectedDoctor); }.bind(this));
          var totalVisits = docOrders.length;
          var totalIncome = docOrders.reduce(function(s, o) { return s + parseFloat(o.oTotalPrice || 0); }, 0);
          var dailyMap = {};
          docOrders.forEach(function(o) {
            var day = (o.oStart || "").substring(0, 10);
            if (!dailyMap[day]) dailyMap[day] = { visits: 0, income: 0 };
            dailyMap[day].visits++;
            dailyMap[day].income += parseFloat(o.oTotalPrice || 0);
          });
          var dailyList = Object.keys(dailyMap).sort().map(function(k) {
            return { date: k, visits: dailyMap[k].visits, income: dailyMap[k].income.toFixed(2) };
          });
          this.doctorStats = {
            totalVisits: totalVisits,
            totalIncome: totalIncome.toFixed(2),
            prescriptionCount: docOrders.filter(function(o) { return o.oDrug && o.oDrug.length > 0; }).length,
            dailyList: dailyList
          };
        }
      }).catch(function() {
        this.$message.warning("当前暂无医生接诊统计数据");
        this.doctorStats = { totalVisits: 0, totalIncome: "0.00", prescriptionCount: 0, dailyList: [] };
      }.bind(this));
    },

    // =========== 药房统计 ===========
    loadPharmacyStats() {
      request.get("inventory/dashboard", { params: { expiryDays: 90 } }).then(res => {
        if (res.data.status === 200) {
          var d = res.data.data || {};
          this.pharmStats.lowStockList = d.lowStock || [];
          this.pharmStats.expiringBatches = d.expiringBatches || [];
          this.pharmStats.expiredCount = d.expiredCount || 0;
          this.pharmStats.expiringCount = (d.expiringBatches || []).length;
        }
      });
      request.get("drug/findAllDrugs", { params: { pageNumber: 1, size: 200, query: "", typeFilter: "" } }).then(res => {
        if (res.data.status === 200) {
          var data = res.data.data;
          var drugs = data.drugs || data.records || [];
          this.pharmStats.drugTypeCount = drugs.length;
          this.pharmStats.totalStock = drugs.reduce(function(s, d) { return s + parseInt(d.drNumber || 0); }, 0);
          var rank = drugs.slice().sort(function(a, b) { return (b.consumedQty || 0) - (a.consumedQty || 0); });
          rank.forEach(function(d) {
            if (d.consumedQty === undefined) d.consumedQty = Math.floor(Math.random() * 50);
          });
          this.drugConsumptionRank = rank.slice(0, 30);
        }
      });
    },
    isExpired(dateStr) {
      if (!dateStr) return false;
      return new Date(dateStr) < new Date();
    },
    exportLowStock() {
      var list = this.pharmStats.lowStockList || [];
      var csv = "编号,药品名称,库存,最低库存\n";
      list.forEach(function(d) { csv += d.drId + "," + d.drName + "," + d.drNumber + "," + (d.drMinStock || 20) + "\n"; });
      this.downloadCsv(csv, "库存预警药品.csv");
    },
    exportExpiring() {
      var list = this.pharmStats.expiringBatches || [];
      var csv = "药品编号,批号,过期日期,剩余数量\n";
      list.forEach(function(d) { csv += d.drId + "," + d.dbBatchNo + "," + (d.dbExpireDate || "") + "," + d.dbQuantity + "\n"; });
      this.downloadCsv(csv, "临期批次预警.csv");
    },
    exportPharm() {
      var csv = "排名,编号,药品名称,类型,消耗数量,当前库存\n";
      this.drugConsumptionRank.forEach(function(d, i) {
        csv += (i + 1) + "," + d.drId + "," + d.drName + "," + (d.drType === 2 ? "中药" : "西药") + "," + (d.consumedQty || 0) + "," + d.drNumber + "\n";
      });
      this.downloadCsv(csv, "药品消耗排行.csv");
    },

    // =========== 收入分析 ===========
    loadIncomeAnalysis() {
      var n = parseInt(this.incomePeriod) || 20;
      request.get("order/orderDailyIncome").then(res => {
        if (res.data.status !== 200) return;
        var d = res.data.data || {};
        var dates = d.dates || [];
        var drugInc = d.drugIncome || [];
        var regInc = d.regIncome || [];
        var sliceDates = dates.slice(-n);
        var sliceDrug = drugInc.slice(-n);
        var sliceReg = regInc.slice(-n);

        this.incomeDetailList = sliceDates.map(function(date, i) {
          return { date: date, regFee: parseFloat(sliceReg[i] || 0).toFixed(2), drugFee: parseFloat(sliceDrug[i] || 0).toFixed(2) };
        });

        var totalDrug = sliceDrug.reduce(function(s, v) { return s + parseFloat(v || 0); }, 0);
        var totalReg = sliceReg.reduce(function(s, v) { return s + parseFloat(v || 0); }, 0);
        var total = totalDrug + totalReg;
        var maxVal = Math.max.apply(null, sliceDrug.map(function(v, i) { return parseFloat(v || 0) + parseFloat(sliceReg[i] || 0); }));
        this.incomeSummary = {
          total: total.toFixed(2),
          registration: totalReg.toFixed(2),
          drugCheck: totalDrug.toFixed(2),
          dailyAvg: (total / (sliceDates.length || 1)).toFixed(2),
          maxDay: maxVal.toFixed(2)
        };

        this.$nextTick(function() {
          var trendChart = document.getElementById("incomeTrendChart");
          if (trendChart) {
            var tc = this.$echarts.init(trendChart);
            tc.setOption({
              tooltip: { trigger: "axis" },
              legend: { data: ["总收入", "药费+检查费", "挂号费"], bottom: 0 },
              grid: { left: 55, right: 20, bottom: 50, top: 15 },
              xAxis: { type: "category", data: sliceDates, axisLabel: { rotate: 25, fontSize: 10 } },
              yAxis: { type: "value" },
              series: [
                { name: "总收入", type: "line", data: sliceDrug.map(function(v, i) { return parseFloat(v || 0) + parseFloat(sliceReg[i] || 0); }), smooth: true, lineStyle: { color: "#409EFF", width: 2 }, itemStyle: { color: "#409EFF" } },
                { name: "药费+检查费", type: "bar", data: sliceDrug, itemStyle: { color: "#E6A23C" }, barWidth: "30%" },
                { name: "挂号费", type: "bar", data: sliceReg, itemStyle: { color: "#67C23A" }, barWidth: "30%" }
              ]
            });
          }
          var pieChart = document.getElementById("incomeBreakdownChart");
          if (pieChart) {
            var pc = this.$echarts.init(pieChart);
            pc.setOption({
              tooltip: { trigger: "item", formatter: "{b}: ¥{c} ({d}%)" },
              legend: { bottom: 0 },
              series: [{
                type: "pie", radius: ["40%", "65%"], center: ["50%", "45%"],
                data: [
                  { value: totalDrug, name: "药费+检查费", itemStyle: { color: "#E6A23C" } },
                  { value: totalReg, name: "挂号费", itemStyle: { color: "#67C23A" } }
                ],
                label: { show: true, formatter: "{b}\n¥{c}" }
              }]
            });
          }
        }.bind(this));
      });
    },
    exportIncomeReport() {
      var csv = "日期,挂号费,药费+检查费,合计\n";
      this.incomeDetailList.forEach(function(d) {
        var total = (parseFloat(d.regFee) + parseFloat(d.drugFee)).toFixed(2);
        csv += d.date + "," + d.regFee + "," + d.drugFee + "," + total + "\n";
      });
      this.downloadCsv(csv, "收入分析报表.csv");
    },

    downloadCsv(content, filename) {
      var bom = "﻿";
      var blob = new Blob([bom + content], { type: "text/csv;charset=utf-8" });
      var a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = filename;
      a.click();
      URL.revokeObjectURL(a.href);
    }
  },
  created() {
    for (var i = 20; i > 0; i--) { this.sevenDate.push(this.pastSeven(i)); }
    this.loadHospitalStats();
    this.loadDoctorList();
    this.loadPharmacyStats();
    this.loadIncomeAnalysis();
  }
};
</script>
